-- ─── migrations/0001_quests.sql ───

-- ═══════════════════════════════════════════════════════════════════════
--  Master-data migration 0001 — QUESTS
--  Unifies the 8 quest_*.json files into a single Supabase table so quests
--  can be edited in the dashboard/SQL instead of hand-maintained JSON.
--  The nested structures stay as JSONB (the Flutter model is unchanged) so
--  this is a low-risk lift. `source_file` + `sort_order` let the export tool
--  regenerate the exact original JSON files for the CDN (client untouched).
--  Run once in the Supabase SQL editor, then load supabase/seed/quests_seed.sql.
-- ═══════════════════════════════════════════════════════════════════════

-- ── Content version registry (for cache-busting / checkVersion) ──────────
create table if not exists public.master_content_version (
  domain      text primary key,
  version     bigint not null default 1,
  updated_at  timestamptz not null default now()
);

create or replace function public.bump_content_version()
  returns trigger language plpgsql as $$
begin
  insert into public.master_content_version(domain, version, updated_at)
  values (tg_argv[0], 1, now())
  on conflict (domain)
    do update set version = master_content_version.version + 1,
                  updated_at = now();
  return null;
end $$;

-- ── Quests ───────────────────────────────────────────────────────────────
create table if not exists public.quests (
  id                  text primary key,
  title               text not null,
  type                text,
  rank                text,
  faction             text not null,
  region              text,
  description         text,
  -- nested structures kept as JSONB (matches the Flutter QuestTemplate model)
  quest_giver         jsonb not null default '{}'::jsonb,
  requirements        jsonb not null default '{}'::jsonb,
  objectives          jsonb not null default '[]'::jsonb,
  rewards             jsonb not null default '{}'::jsonb,
  repeatable          boolean not null default false,
  daily               boolean not null default false,
  quest_chain_next    text,
  -- popup / tutorial metadata (only on a handful of msq_* quests)
  popup               boolean not null default false,
  popup_trigger       text,
  popup_level         int,
  popup_prerequisite  text,
  -- round-trip bookkeeping so export can rebuild the original CDN files 1:1
  source_file         text,
  sort_order          int not null default 0,
  updated_at          timestamptz not null default now()
);

create index if not exists quests_faction_idx on public.quests (faction);
create index if not exists quests_type_idx    on public.quests (type);
create index if not exists quests_source_idx  on public.quests (source_file, sort_order);
-- query quests by required prerequisite quest, etc. (JSONB GIN)
create index if not exists quests_requirements_gin on public.quests using gin (requirements);

-- touch updated_at on every write
create or replace function public.touch_updated_at()
  returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

drop trigger if exists quests_touch on public.quests;
create trigger quests_touch before update on public.quests
  for each row execute function public.touch_updated_at();

-- bump the 'quests' content version on any change (per statement = one bump/batch)
drop trigger if exists quests_bump_version on public.quests;
create trigger quests_bump_version after insert or update or delete on public.quests
  for each statement execute function public.bump_content_version('quests');

-- ── RLS: master data is public read-only; writes only via service role ───
alter table public.quests enable row level security;
drop policy if exists quests_public_read on public.quests;
create policy quests_public_read on public.quests for select using (true);

alter table public.master_content_version enable row level security;
drop policy if exists mcv_public_read on public.master_content_version;
create policy mcv_public_read on public.master_content_version for select using (true);


-- ─── migrations/0002_shops.sql ───

-- ═══════════════════════════════════════════════════════════════════════
--  Master-data migration 0002 — SHOPS
--  Moves shop_inventory.json (42 shops, 372 stocked items across 72 category
--  labels) into Supabase. Unlike quests (JSONB blob), shops are NORMALISED
--  into shops + shop_items so per-item stock / price can be tuned row-by-row
--  (the actual maintenance pain). export_shops.py re-nests rows into the exact
--  {meta, shops:[{categories:[{items}]}]} JSON the client reads (unchanged).
--  Run after 0001; requires the master_content_version helper from 0001.
-- ═══════════════════════════════════════════════════════════════════════

create table if not exists public.shops (
  id            text primary key,
  name          text not null,
  faction       text,
  buy_currency  text,
  description   text,
  sort_order    int not null default 0,
  updated_at    timestamptz not null default now()
);

create table if not exists public.shop_items (
  id             bigint generated always as identity primary key,
  shop_id        text not null references public.shops(id) on delete cascade,
  category       text not null,
  item_id        text not null,
  stock          int not null default 0,
  refresh_time   int not null default 0,
  price_modifier numeric not null default 1.0,
  sort_order     int not null default 0,
  updated_at     timestamptz not null default now(),
  unique (shop_id, category, item_id)
);

create index if not exists shop_items_shop_idx on public.shop_items (shop_id, sort_order);
create index if not exists shop_items_item_idx on public.shop_items (item_id);

-- touch updated_at (reuses touch_updated_at() from 0001)
drop trigger if exists shops_touch on public.shops;
create trigger shops_touch before update on public.shops
  for each row execute function public.touch_updated_at();
drop trigger if exists shop_items_touch on public.shop_items;
create trigger shop_items_touch before update on public.shop_items
  for each row execute function public.touch_updated_at();

-- bump the 'shops' content version on any change (reuses bump_content_version)
drop trigger if exists shops_bump_version on public.shops;
create trigger shops_bump_version after insert or update or delete on public.shops
  for each statement execute function public.bump_content_version('shops');
drop trigger if exists shop_items_bump_version on public.shop_items;
create trigger shop_items_bump_version after insert or update or delete on public.shop_items
  for each statement execute function public.bump_content_version('shops');

-- RLS: public read-only; writes only via service role.
alter table public.shops enable row level security;
drop policy if exists shops_public_read on public.shops;
create policy shops_public_read on public.shops for select using (true);

alter table public.shop_items enable row level security;
drop policy if exists shop_items_public_read on public.shop_items;
create policy shop_items_public_read on public.shop_items for select using (true);


-- ─── migrations/0003_raid_events.sql ───

-- ═══════════════════════════════════════════════════════════════════════
--  Master-data migration 0003 — RAID EVENTS (live/timed content)
--  raid_boss_event.json (the timed raid boss definitions) → public.raid_events.
--  Scalars as columns; nested (entry_requirements / spawn_monster_id / phases /
--  clear_rewards) as JSONB, matching the RaidEvent model. export_raids.py
--  rebuilds {raids:[...]} for the CDN (client unchanged).
--  Run after 0001 (needs touch_updated_at + bump_content_version).
--
--  NOTE: quest_events.json currently holds 0 quests — it is already covered by
--  the quests migration (0001) which round-trips it as an empty file; no
--  separate table is needed until timed quest-events actually exist.
-- ═══════════════════════════════════════════════════════════════════════

create table if not exists public.raid_events (
  raid_id                 text primary key,
  name                    text not null,
  region                  text,
  min_level               int,
  recommended_party_size  int,
  max_player              int,
  spawn_time_ends         int,
  time_limit              int,
  boss_monster_id         int,
  raid_type               text,
  max_entry               int,
  entry_requirements      jsonb not null default '[]'::jsonb,
  spawn_monster_id        jsonb not null default '[]'::jsonb,
  phases                  jsonb not null default '[]'::jsonb,
  clear_rewards           jsonb not null default '{}'::jsonb,
  sort_order              int not null default 0,
  updated_at              timestamptz not null default now()
);

create index if not exists raid_events_region_idx on public.raid_events (region);

drop trigger if exists raid_events_touch on public.raid_events;
create trigger raid_events_touch before update on public.raid_events
  for each row execute function public.touch_updated_at();

drop trigger if exists raid_events_bump_version on public.raid_events;
create trigger raid_events_bump_version after insert or update or delete on public.raid_events
  for each statement execute function public.bump_content_version('raid_events');

alter table public.raid_events enable row level security;
drop policy if exists raid_events_public_read on public.raid_events;
create policy raid_events_public_read on public.raid_events for select using (true);


