insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_005', 'The Shape of a Soldier', 'tutorial', 'D', 'CONCORDIUM', 'NEXUS_CORE', 'Commander Vale''s field report reached Nexus Core faster than you expected. Instructor Kael — the Concordium''s master trainer, a veteran who fought in the earliest post-Schism skirmishes — has summoned you personally. Before the Concordium trusts you with the Cradle''s defense, you must choose your path. The Aethel Cradle wasn''t rebuilt by generalists.', '{"npc_id": "npc_concordium_class_trainer", "name": "Instructor Kael", "location": "NEXUS_CORE"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_conc_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_concordium_class_trainer", "count": 1, "description": "Speak with Instructor Kael at Nexus Core. (Instructor Kael at Nexus Core Training Academy)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "description": "Open the class selection screen and review available classes."}, {"type": "kill", "target": "FOREST_SLIME", "count": 3, "description": "Defeat Forest Slimes to demonstrate your training."}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_iron_sword", "quantity": 1}, {"item_id": "armor_guard_chainmail", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_conc_006', true, 'on_quest_complete', 4, 'fq_conc_004', 'quest_concordium.json', 4)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_006', 'What the Schism Left Behind', 'story', 'D', 'CONCORDIUM', 'BROKEN_CIVIL_QUARTER', 'The Broken Civil Quarter was once the beating heart of unified Nexus — before the Great Schism tore the Concordium into three factions and left these streets to rot. Concordium engineers have located a viable breach point to reclaim the district, but Tunnel Crawlers have nested in the main access corridor. Commander Vale''s orders are direct: clear it, stake the Concordium flag, and remind Xylos that unity is still possible. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "BROKEN_CIVIL_QUARTER"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_conc_005"]}'::jsonb, '[{"type": "kill", "target": "TUNNEL_CRAWLER", "count": 6, "description": "Defeat Tunnel Crawlers at the main breach."}, {"type": "collect", "target": "crawler_chitin", "count": 1, "description": "Collect crawler chitin (x1). [Item: Crawler Chitin]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "mat_iron_ore", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_conc_007', false, NULL, NULL, NULL, 'quest_concordium.json', 5)
