values ('fq_conc_032', 'Iron Carapace', 'hunt', 'A', 'CONCORDIUM', 'CRADLE_EXPANSE', 'Aethel Iron Carapaces threaten orbital supply lanes. (Location: Cradle Expanse, Officer Valen) Destroy them to keep the lanes open for Concordium logistics.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 31, "reputation_required": 1800, "required_quests": ["fq_conc_031"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 6, "description": "Defeat Aethel Iron Carapaces near supply lanes."}, {"type": "collect", "target": "carapace_fragment", "count": 3, "description": "Collect carapace fragment (x3). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 1000, "currency": 550, "crd": 275, "rep": 550, "items": [{"item_id": "rusted_plate", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_conc_033', false, NULL, NULL, NULL, 'quest_concordium.json', 31)
