values ('fq_conc_035', 'The Deep Hunt', 'boss', 'A', 'CONCORDIUM', 'CRADLE_EXPANSE', 'Aethel Abyssal Reavers have emerged — the vanguard of something far worse. (Location: Cradle Expanse, Officer Valen) Hunt them and collect intelligence.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 34, "reputation_required": 1980, "required_quests": ["fq_conc_034"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 3, "description": "Defeat Aethel Abyssal Reavers in the Expanse."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 1600, "currency": 850, "crd": 425, "rep": 850, "items": [{"item_id": "event_horizon_fragment", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_036', false, NULL, NULL, NULL, 'quest_concordium.json', 34)
