values ('fq_conc_048', 'The Tyrant''s Domain', 'boss', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'A Crystal Tyrant has claimed territory in the chasm. (Location: Void Echo Chasm, Officer Valen) Its crystal shell deflects conventional weaponry. Find its weakness.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 47, "reputation_required": 2760, "required_quests": ["fq_conc_047"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 1, "description": "Defeat the Crystal Tyrant in the chasm."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 3800, "currency": 1900, "crd": 950, "rep": 1100, "items": [{"item_id": "quantum_distortion_stone", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_049', false, NULL, NULL, NULL, 'quest_concordium.json', 47)
