values ('fq_conc_051', 'Soul Fragmenter', 'boss', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'The Soul Fragmenter — a void entity that tears apart consciousness itself — has been detected. (Location: Void Echo Chasm, Officer Valen) Engage before it can multiply.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 50, "reputation_required": 2940, "required_quests": ["fq_conc_050"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 1, "description": "Defeat the Soul Fragmenter."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "memory_fragment_chip", "quantity": 5}, {"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_052', false, NULL, NULL, NULL, 'quest_concordium.json', 50)
