values ('fq_conc_054', 'Chrono Distortion', 'boss', 'S', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Chrono Wraiths are tearing holes in the fabric of time within the chasm. (Location: Void Echo Chasm, Officer Valen) Each Wraith threatens to create a permanent temporal rift.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 53, "reputation_required": 3120, "required_quests": ["fq_conc_053"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "description": "Banish the Chrono Wraiths from the time rifts."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3200, "crd": 1600, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_055', false, NULL, NULL, NULL, 'quest_concordium.json', 53)
