values ('fq_conc_057', 'Tyrant''s Fall', 'boss', 'S', 'CONCORDIUM', 'SHATTERED_HEART', 'Crystal Tyrants have organized into a hunting pack in the Heart. (Location: Shattered Heart, Officer Valen) This coordinated behavior is unprecedented — and terrifying.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 56, "reputation_required": 3300, "required_quests": ["fq_conc_056"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "description": "Defeat two Crystal Tyrants in the Heart."}, {"type": "kill", "target": "DRAKE_MINION", "count": 4, "description": "Clear Drake Minions from the Tyrant hunting grounds."}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2300, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_058', false, NULL, NULL, NULL, 'quest_concordium.json', 56)
