values ('fq_iron_069', 'Titan Mobilization', 'story', 'S', 'IRON_HEGEMONY', 'AETHEL_SIPHON_CORE', 'Intelligence confirms: the Gravity Titan is mobilizing. (Location: Aethel Siphon Core, Commander Drax) The Hegemony prepares for the largest military operation in our history.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 68, "reputation_required": 230, "required_quests": ["fq_iron_068"]}'::jsonb, '[{"type": "collect", "target": "monster_material", "count": 3, "desc": "Collect Titan mobilization intelligence.", "description": "Collect monster material (x3). [Item: Monster Material]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Defeat a Jotunn scout for the Titan.", "description": "Defeat Gigantic Jotunn (x1)."}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "gravity_well_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_070', false, NULL, NULL, NULL, 'quest_iron.json', 68)
