insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_007', 'Fire Against Fire', 'story', 'D', 'STARFORGED_LEGION', 'SCORCHED_BADLANDS', 'Ash Hounds are fire given form and instinct — creatures that emerged from the Scorched Badlands'' aethel-charged volcanic substrate, running on combustion and predatory rage. Sergeant Korg — whose burn scars on his left arm are a record of his first Ash Hound encounter — explains the Legion''s approach to fire-creatures: ''You do not fear fire. You use fire. Your weapons are fire. Your will is fire. The Hound does not get to be the only thing burning.'' Hunt them.', '{"npc_id": "npc_drill_sergeant_korg", "name": "Centurion Valka", "location": "SCORCHED_BADLANDS"}'::jsonb, '{"min_level": 6, "reputation_required": 30, "required_quests": ["fq_star_006"]}'::jsonb, '[{"type": "kill", "target": "ASH_HOUND", "count": 5, "description": "Hunt Ash Hounds."}, {"type": "collect", "target": "ember_fang", "count": 3, "description": "Collect ember fang (x3). [Item: Ember Fang]"}]'::jsonb, '{"exp": 120, "currency": 70, "crd": 0, "rep": 70, "items": [{"item_id": "animal_fang", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_star_008', false, NULL, NULL, NULL, 'quest_legion.json', 6)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_star_008', 'Poison the Poisoners', 'story', 'D', 'STARFORGED_LEGION', 'SCORCHED_BADLANDS', 'Dune Scorpions have poisoned three Legion water reservoirs, killing a supply crew and triggering an emergency ration restriction across the Scorched Badlands forward camp. Scout Jace''s assessment is terse and accurate: these are not random attacks. The Scorpions are territorial and the Legion has established its camp in the center of their territorial zone. The Legion''s response to territorial disputes is historically simple. Exterminate the competition. Recover the stingers for antivenom production. Waste nothing.', '{"npc_id": "npc_dune_scout", "name": "Centurion Valka", "location": "SCORCHED_BADLANDS"}'::jsonb, '{"min_level": 7, "reputation_required": 35, "required_quests": ["fq_star_007"]}'::jsonb, '[{"type": "kill", "target": "DUNE_SCORPION", "count": 6, "description": "Exterminate Scorpions. [Dune Scorpion]"}, {"type": "collect", "target": "scorpion_stinger", "count": 3, "description": "Collect scorpion stinger (x3). [Item: Scorpion Stinger]"}]'::jsonb, '{"exp": 180, "currency": 100, "crd": 0, "rep": 100, "items": [{"item_id": "scorpion_stinger", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_star_009', false, NULL, NULL, NULL, 'quest_legion.json', 7)
