values ('fq_merid_010', 'Hostile Inventory', 'story', 'D', 'MERIDIAN_CARTEL', 'SMUGGLER_JUNGLE', 'A Contraband Golem — a war construct that a previous black-market operation used as a walking vault, stuffed with illegal goods before the operation was shut down by whoever they were dealing with — now blocks the main Cartel trade route, attacking anyone who approaches. (Location: Smuggler Jungle, Don Vercelli) Don Vercelli Mox does not ask what is inside it. He already knows, because the original operator owed the Cartel a very large sum. ''Consider this a repossession,'' he says, adjusting his cufflinks.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "SMUGGLER_JUNGLE"}'::jsonb, '{"min_level": 9, "reputation_required": 40, "required_quests": ["fq_merid_009"]}'::jsonb, '[{"type": "kill", "target": "CONTRABAND_GOLEM", "count": 2, "desc": "Liquidate Contraband Golems.", "description": "Defeat Contraband Golem (x2)."}, {"type": "collect", "target": "contraband_core", "count": 1, "desc": "Seize the Golem''s inventory manifest.", "description": "Collect contraband core (x1). [Item: Contraband Core]"}]'::jsonb, '{"exp": 300, "currency": 180, "crd": 0, "rep": 180, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_merid_011', false, NULL, NULL, NULL, 'quest_meridian.json', 9)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_merid_011', 'The Heart of the Deal', 'story', 'C', 'MERIDIAN_CARTEL', 'BLACK_DOCK_MARKET', 'The Black Dock Market is the Cartel''s crown jewel — an underground trading hub where every faction, every faction-adjacent operator, and every independent on Xylos eventually comes to do business. Don Vercelli Mox built it from a single smuggler''s berth twenty years ago, deal by deal. Now the supply chain feeding it is under pressure from multiple competitors. Before you operate at this level of Cartel business, you need to understand what is at stake. Enter the Black Dock. See what the Cartel protects.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli Mox", "location": "BLACK_DOCK_MARKET"}'::jsonb, '{"min_level": 10, "reputation_required": 45, "required_quests": ["fq_merid_010"]}'::jsonb, '[{"type": "travel", "target": "BLACK_DOCK_MARKET", "count": 1, "desc": "Enter the Black Dock Market.", "description": "Travel to BLACK DOCK MARKET. (Travel to: Black Dock Market)"}, {"type": "collect", "target": "thick_hide", "count": 2, "desc": "File your market security assessment.", "description": "Collect thick hide (x2). [Item: Thick Hide]"}]'::jsonb, '{"exp": 280, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "con_minor_stim_pack", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_merid_012', false, NULL, NULL, NULL, 'quest_meridian.json', 10)
