values ('fq_merid_034', 'Behemoth Short', 'boss', 'A', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'Aethel Corrupted Behemoths are undercutting Cartel prices by destroying our facilities. (Location: Cradle Expanse, Don Vercelli) Short their existence.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 33, "reputation_required": 1920, "required_quests": ["fq_merid_033"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 2, "desc": "Short the Behemoth position.", "description": "Defeat Aethel Corrupted Behemoth (x2)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "File zero-damage facility report.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 1600, "currency": 850, "crd": 425, "rep": 850, "items": [{"item_id": "aethel_fragment", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_merid_035', false, NULL, NULL, NULL, 'quest_meridian.json', 33)
