values ('fq_merid_037', 'Drake Liquidation', 'boss', 'A', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'The Ashen Drake has returned. (Location: Cradle Expanse, Don Vercelli) The Cartel board has authorized a complete liquidation. Every part of the Drake is profitable.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 36, "reputation_required": 2100, "required_quests": ["fq_merid_036"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Complete Drake liquidation.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "ancient_scale", "count": 1, "desc": "File Drake asset recovery report.", "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 900, "items": [{"item_id": "drake_heart", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_merid_038', false, NULL, NULL, NULL, 'quest_meridian.json', 36)
