values ('fq_merid_045', 'Behemoth Depreciation', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Corrupted Behemoths are depreciating Cartel void assets. (Location: Void Echo Chasm, Don Vercelli) Accelerate their depreciation — to zero.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 44, "reputation_required": 2580, "required_quests": ["fq_merid_044"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Accelerate Behemoth depreciation.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Report asset recovery status.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_046', false, NULL, NULL, NULL, 'quest_meridian.json', 44)
