values ('fq_merid_046', 'Fragmenter Futures', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Soul Fragmenters disrupt Cartel personnel productivity. (Location: Void Echo Chasm, Don Vercelli) Every hour of lost work is lost profit. Terminate the productivity drain.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 45, "reputation_required": 2640, "required_quests": ["fq_merid_045"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 2, "desc": "Terminate Fragmenter productivity drain.", "description": "Defeat Soul Fragmenter (x2)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Report restored productivity metrics.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 3000, "currency": 1600, "crd": 800, "rep": 1000, "items": [{"item_id": "brainwave_oscillator", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_047', false, NULL, NULL, NULL, 'quest_meridian.json', 45)
