values ('fq_merid_051', 'Risk Management', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Soul Fragmenters represent unacceptable operational risk. (Location: Void Echo Chasm, Don Vercelli) Cartel Risk Management mandates their elimination.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 50, "reputation_required": 2940, "required_quests": ["fq_merid_050"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "desc": "Eliminate operational risk.", "description": "Defeat Soul Fragmenter (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "File Risk Management completion.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "brainwave_reader", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_052', false, NULL, NULL, NULL, 'quest_meridian.json', 50)
