values ('fq_merid_052', 'Total Market Control', 'hunt', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Operation Total Market Control. (Location: Void Echo Chasm, Don Vercelli) Eliminate all unlicensed void entities. The Cartel owns this dimension now.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 51, "reputation_required": 3000, "required_quests": ["fq_merid_051"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 8, "desc": "Eliminate unlicensed Reavers.", "description": "Defeat Void Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Eliminate unlicensed Channelers.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 4500, "currency": 2200, "crd": 1100, "rep": 1500, "items": [{"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_053', false, NULL, NULL, NULL, 'quest_meridian.json', 51)
