values ('fq_merid_053', 'Stalker Hostile Bid', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'A Void Stalker is making a hostile bid for Cartel void operations. (Location: Void Echo Chasm, Don Vercelli) Reject the bid — with extreme prejudice.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 52, "reputation_required": 3060, "required_quests": ["fq_merid_052"]}'::jsonb, '[{"type": "kill", "target": "VOID_STALKER", "count": 1, "desc": "Reject the Stalker''s hostile bid.", "description": "Defeat Void Stalker (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm hostile bid rejection.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "entropy_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_054', false, NULL, NULL, NULL, 'quest_meridian.json', 52)
