values ('fq_merid_056', 'Jotunn Market Cap', 'boss', 'S', 'MERIDIAN_CARTEL', 'SHATTERED_HEART', 'Gigantic Jotunns have the largest market cap in the Heart. (Location: Shattered Heart, Don Vercelli) Reduce their valuation to zero.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 55, "reputation_required": 3240, "required_quests": ["fq_merid_055"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Reduce Jotunn market cap.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "File devaluation report.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_057', false, NULL, NULL, NULL, 'quest_meridian.json', 55)
