values ('fq_merid_097', 'The Final Quarter', 'story', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'The final quarter of operations. (Location: Prima Materia Forge, Don Vercelli) Consolidate all Cartel assets and prepare the closing balance sheet.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 96, "reputation_required": 530, "required_quests": ["fq_merid_096"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Consolidate Jotunn assets.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Close Harbinger accounts.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "File the closing balance sheet.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_098', false, NULL, NULL, NULL, 'quest_meridian.json', 95)
