values ('fq_omni_033', 'Carapace Analysis', 'hunt', 'A', 'OMNICORP', 'CRADLE_EXPANSE', 'Aethel Iron Carapaces have armor superior to Omnicorp alloys. (Location: Cradle Expanse, Tech Officer 404) Reverse-engineer through systematic deconstruction.', '{"npc_id": "npc_omnicorp_technician", "name": "Tech Officer 404", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 32, "reputation_required": 1860, "required_quests": ["fq_omni_032"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 6, "desc": "Deconstruct Iron Carapaces for analysis.", "description": "Defeat Aethel Iron Carapace (x6)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Submit alloy analysis.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 1400, "currency": 750, "crd": 375, "rep": 750, "items": [{"item_id": "rusted_plate", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_omni_034', false, NULL, NULL, NULL, 'quest_omnicorp.json', 31)
