values ('fq_omni_045', 'Behemoth Error Correction', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Aethel Corrupted Behemoths are error cascades in the void system. (Location: Void Echo Chasm, Warden AI) Execute Error Correction Protocol.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 44, "reputation_required": 2580, "required_quests": ["fq_omni_044"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Execute Error Correction Protocol.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Confirm errors corrected.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_046', false, NULL, NULL, NULL, 'quest_omnicorp.json', 43)
