values ('fq_omni_048', 'Jotunn Resource Conflict', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'A Gigantic Jotunn occupies a high-value resource node. (Location: Void Echo Chasm, Director Sterling) Resolve the resource conflict through Jotunn process termination.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 47, "reputation_required": 2760, "required_quests": ["fq_omni_047"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Terminate Jotunn process.", "description": "Defeat Gigantic Jotunn (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm resource node secured.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1000, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_049', false, NULL, NULL, NULL, 'quest_omnicorp.json', 46)
