values ('fq_omni_073', 'Quality Assurance', 'boss', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Corrupted Behemoths are defective products contaminating the Forge. (Location: Prima Materia Forge, Director Sterling) Execute Product Recall and Disposal.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 72, "reputation_required": 4260, "required_quests": ["fq_omni_072"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Execute Product Recall and Disposal.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "File QA clearance report.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2200, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_074', false, NULL, NULL, NULL, 'quest_omnicorp.json', 71)
