values ('fq_omni_087', 'Tri-Process Termination', 'boss', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'All three Apex processes — Drake, Titan, Harbinger. (Location: Prima Materia Forge, Director Sterling) Execute concurrent termination. System resources: unlimited.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 86, "reputation_required": 5100, "required_quests": ["fq_omni_086"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Terminate Drake process.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Terminate Titan process.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Terminate Harbinger process.", "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 6000, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_088', false, NULL, NULL, NULL, 'quest_omnicorp.json', 85)
