insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_002', 'Pruning as Prayer', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'GLOWVINE_FOREST', 'Acolyte Mera, who tends the Glowvine Forest''s ritual paths, speaks with a reverence that the other factions find incomprehensible: the Forest Barklings are children of the Shard, born from the same corrupted soil that once was holy. They have grown wild because the Shard is dreaming — the Great Severance was not a catastrophe but a divine withdrawal, and its aftermath is the Shard''s sleeping breath reshaping the world. Each Barkling calmed is a prayer. Each cut must be made with the intention to restore, not to destroy.', '{"npc_id": "npc_acolyte_mera", "name": "Elder Malakor", "location": "GLOWVINE_FOREST"}'::jsonb, '{"min_level": 1, "reputation_required": 5, "required_quests": ["fq_shard_001"]}'::jsonb, '[{"type": "kill", "target": "FOREST_BARKLING", "count": 5, "description": "Prune Forest Barklings."}, {"type": "collect", "target": "bark_fragment", "count": 2, "description": "Collect bark fragment (x2). [Item: Bark Fragment]"}]'::jsonb, '{"exp": 55, "currency": 35, "crd": 0, "rep": 35, "items": [{"item_id": "vine_fiber", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_shard_003', false, NULL, NULL, NULL, 'quest_shard.json', 1)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_003', 'The Lost Are Not Evil', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'GLOWVINE_FOREST', 'Brother Silas, who walks the forest''s perimeter each dawn reciting Shard invocations against the day the Severance ends, explains: Glowvine Stalkers are not hunters by nature — they were once benign creatures of the sacred forest, corrupted when the Industrial factions began drilling near the forest''s aethel nodes. (Location: Glowvine Forest, Brother Silas) They hunt because they are in pain. They are lost because the Shard''s light has been dimmed by others'' greed. The Children do not condemn the lost. They guide them back, even if guiding requires force.', '{"npc_id": "npc_forest_acolyte", "name": "Elder Malakor", "location": "GLOWVINE_FOREST"}'::jsonb, '{"min_level": 2, "reputation_required": 10, "required_quests": ["fq_shard_002"]}'::jsonb, '[{"type": "kill", "target": "GLOWVINE_STALKER", "count": 5, "description": "Guide Glowvine Stalkers."}, {"type": "collect", "target": "glowvine_seed", "count": 2, "description": "Collect glowvine seed (x2). [Item: Glowvine Seed]"}]'::jsonb, '{"exp": 70, "currency": 40, "crd": 0, "rep": 40, "items": [{"item_id": "dark_energy_fragment", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_004', false, NULL, NULL, NULL, 'quest_shard.json', 2)
